-- Hosbah (MH-577 I6): an SMTP relay credential dedicated to one app — a Stalwart "individual"
-- principal created the same way as a mailbox (mail.mailbox op), used only to authenticate outgoing
-- SMTP, never to receive mail or sign in as a person. password_sealed is generated by Hosbah, sealed
-- with the team DEK bound to "mailrelay:<id>", and shown to the caller exactly once (at creation or
-- rotation); it is re-sealed to the target agent's own key for each operation, the same way every
-- other agent-op secret travels, so operations.params never holds a plaintext credential. attached
-- records whether mail_attach_relay has last pushed the app's SMTP_* env vars for this credential.
ALTER TABLE mail_relay_credentials ADD CONSTRAINT mail_relay_credentials_status_check CHECK (status IN ('new', 'creating', 'ready', 'failed', 'removing'));
ALTER TABLE mail_relay_credentials ADD CONSTRAINT mail_relay_credentials_local_part_check CHECK (local_part ~ '^[a-z0-9][a-z0-9._-]{0,62}$');
ALTER TABLE mail_relay_credentials ADD CONSTRAINT mail_relay_credentials_sealed_check CHECK (password_sealed LIKE 'csv1:%');
CREATE UNIQUE INDEX mail_relay_credentials_domain_local_key ON mail_relay_credentials (mail_domain_id, local_part);
CREATE UNIQUE INDEX mail_relay_credentials_id_team_key ON mail_relay_credentials (id, team_id);
CREATE INDEX mail_relay_credentials_domain_idx ON mail_relay_credentials (mail_domain_id);
CREATE INDEX mail_relay_credentials_app_idx ON mail_relay_credentials (app_id);
-- No FK to mail_domains or apps (different modules / schema load order); enforced in internal/mail.
